curl -X PATCH 'https://api.miro.com/api/v1/scim/Groups/{id}' \
  -H 'Authorization: Bearer <token>' \
  -H 'Content-Type: application/scim+json'
  -d '{
  "schemas": [
    "urn:ietf:params:scim:api:messages:2.0:PatchOp"
  ],
  "Operations": [
    {
      "op": "add",
      "path": "members",
      "value": [
        {
          "value": "<userId>"
        }
      ]
    }
  ]
}'

